                    call_id: call_id.clone(),
                    name: name.clone(),
                    args: args.clone(),
                });
                contributions.push(1);
            }
            SessionEvent::ToolReturned {
                call_id, content, ..
            } => {
                messages.push(Item::ToolResult {
                    call_id: call_id.clone(),
                    content: content.clone(),
                });
                contributions.push(1);
            }
