    let ev = vec![SessionEvent::ToolDeferred { deferral_id: "x".into(), call_id: "c".into(), name: "n".into(), args: serde_json::json!({"a": 9_007_199_254_740_993_u64, "b": -42, "f": 1250.75}), prompt: "p".into(), handoff_path: vec![], ts: Timestamp::from_second(1_700_000_000).unwrap() }];
